parameters.jsCode:
const labels = $input.all();
const outputs = $("Split_Out").all();

const pairedLabels = outputs.map((output) => {
  const matchedLabel = labels.find(
    (label) => label?.json?.name === output?.json["output.labels"],
  );
  return matchedLabel ? { ...output.json, ...matchedLabel.json } : output.json;
});

const uniquePairedLabels = Array.from(
  new Set(pairedLabels.map(JSON.stringify)),
).map(JSON.parse);

return uniquePairedLabels.map((item) => ({ json: item }));

